import{J as e,n as t,q as n,st as r}from"./chunks/framework.dvm6fd6R.js";var i=JSON.parse(`{"title":"Class: NetherNetServer","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: NetherNetServer"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/nethernet/classes/NetherNetServer"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/nethernet/classes/NetherNetServer"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/nethernet/src"}},"headers":[],"relativePath":"api/@jsprismarine/nethernet/classes/NetherNetServer.md","filePath":"api/@jsprismarine/nethernet/classes/NetherNetServer.md","lastUpdated":1794485000000}`),a={name:`api/@jsprismarine/nethernet/classes/NetherNetServer.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/nethernet</a> / NetherNetServer</p><h1 id="class-nethernetserver" tabindex="-1">Class: NetherNetServer <a class="header-anchor" href="#class-nethernetserver" aria-label="Permalink to “Class: NetherNetServer”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L64" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:64</a></p><p>NetherNet&#39;s server side: turns each client&#39;s offer into an answer over a WebRTC driver, and keeps the connection it negotiates. Offers arrive through <a href="#handleoffer">NetherNetServer.handleOffer</a>, from HTTP signaling, or from LAN discovery on UDP 7551 once <a href="#listen">NetherNetServer.listen</a> binds it.</p><p>Events: <code>openConnection</code> (Connection), once both channels are open and the peer is connected; <code>closeConnection</code> (connection ID, reason); <code>encapsulated</code> (message, connection ID).</p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h2><ul><li><code>EventEmitter</code></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new NetherNetServer</strong>(<code>options</code>): <code>NetherNetServer</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L79" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:79</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#nethernetserveroptions"><code>NetherNetServerOptions</code></a></p><p>The driver and how to build each peer.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>NetherNetServer</code></p><h4 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to “Overrides”">​</a></h4><p><code>EventEmitter.constructor</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="connections" tabindex="-1">connections <a class="header-anchor" href="#connections" aria-label="Permalink to “connections”">​</a></h3><blockquote><p><code>readonly</code> <strong>connections</strong>: <code>Map</code>&lt;<code>bigint</code>, <a href="./Connection.html"><code>Connection</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L67" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:67</a></p><p>Every connection by the ID its client picked, opened or still negotiating.</p><hr><h3 id="networkid" tabindex="-1">networkId <a class="header-anchor" href="#networkid" aria-label="Permalink to “networkId”">​</a></h3><blockquote><p><code>readonly</code> <strong>networkId</strong>: <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L65" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:65</a></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="close" tabindex="-1">close() <a class="header-anchor" href="#close" aria-label="Permalink to “close()”">​</a></h3><blockquote><p><strong>close</strong>(<code>reason?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L238" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:238</a></p><p>Closes every connection and LAN discovery.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reason" tabindex="-1">reason? <a class="header-anchor" href="#reason" aria-label="Permalink to “reason?”">​</a></h5><p><code>string</code> = <code>&#39;Server closed&#39;</code></p><p>Why, which each connection&#39;s <code>closeConnection</code> carries.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="handlecandidate" tabindex="-1">handleCandidate() <a class="header-anchor" href="#handlecandidate" aria-label="Permalink to “handleCandidate()”">​</a></h3><blockquote><p><strong>handleCandidate</strong>(<code>signal</code>, <code>respond?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L189" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:189</a></p><p>Adds a candidate a client trickled after its offer.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="signal" tabindex="-1">signal <a class="header-anchor" href="#signal" aria-label="Permalink to “signal”">​</a></h5><p><a href="./SignalStructure.html"><code>SignalStructure</code></a></p><p>The <code>CANDIDATEADD</code>.</p><h5 id="respond" tabindex="-1">respond? <a class="header-anchor" href="#respond" aria-label="Permalink to “respond?”">​</a></h5><p><a href="./../#signalresponder"><code>SignalResponder</code></a></p><p>Sends a signal back to that client.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="handleoffer" tabindex="-1">handleOffer() <a class="header-anchor" href="#handleoffer" aria-label="Permalink to “handleOffer()”">​</a></h3><blockquote><p><strong>handleOffer</strong>(<code>signal</code>, <code>respond</code>, <code>proof?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L93" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:93</a></p><p>Negotiates a peer for a client&#39;s offer and sends the answer, with every candidate, through <code>respond</code>. An offer for a connection ID already in use is ignored.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="signal-1" tabindex="-1">signal <a class="header-anchor" href="#signal-1" aria-label="Permalink to “signal”">​</a></h5><p><a href="./SignalStructure.html"><code>SignalStructure</code></a></p><p>The <code>CONNECTREQUEST</code>.</p><h5 id="respond-1" tabindex="-1">respond <a class="header-anchor" href="#respond-1" aria-label="Permalink to “respond”">​</a></h5><p><a href="./../#signalresponder"><code>SignalResponder</code></a></p><p>Sends a signal back to that client.</p><h5 id="proof" tabindex="-1">proof? <a class="header-anchor" href="#proof" aria-label="Permalink to “proof?”">​</a></h5><p><a href="./../#identityproof"><code>IdentityProof</code></a></p><p>What the offer&#39;s <code>a=identity</code> proves, when the caller took it out of the offer already; read from the offer when absent.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="listen" tabindex="-1">listen() <a class="header-anchor" href="#listen" aria-label="Permalink to “listen()”">​</a></h3><blockquote><p><strong>listen</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L220" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:220</a></p><p>Binds UDP 7551 and answers LAN discovery: requests with the advertisement, and signals addressed to this server&#39;s network ID.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the port cannot be bound.</p><hr><h3 id="setadvertisement" tabindex="-1">setAdvertisement() <a class="header-anchor" href="#setadvertisement" aria-label="Permalink to “setAdvertisement()”">​</a></h3><blockquote><p><strong>setAdvertisement</strong>(<code>advertisement</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3e9ed994316b88ebf73c9b8bb2e8de6410d38f41/packages/nethernet/src/NetherNetServer.ts#L211" target="_blank" rel="noreferrer">packages/nethernet/src/NetherNetServer.ts:211</a></p><p>Sets what a LAN discovery request is answered with.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="advertisement" tabindex="-1">advertisement <a class="header-anchor" href="#advertisement" aria-label="Permalink to “advertisement”">​</a></h5><p><code>Buffer</code></p><p>The bytes <code>encodeLanAdvertisement</code> makes.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,90)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};